using System.Security.Cryptography;
using KillerPdf.Engine.Filters;
using Xunit;

namespace KillerPdf.Engine.Tests.Filters;

public sealed class PdfJpegIdctTests
{
    // Mixed-frequency, odd-sized fixtures encoded with Pillow at quality 87 and no subsampling.
    // Sample hashes preserve the decoder's established output before IDCT arithmetic was hoisted.
    [Theory]
    [InlineData(0, 1, 17, 13, "87230649E3E2AB47452EB665D7CDEC501501CB3EDADA8C85C8C3D77F830CE634")]
    [InlineData(0, 2, 9, 7, "A49739DF67F68A2317E454D85DB3918A3DE79C0179210A8EBE5B17D4DCF6EEF9")]
    [InlineData(0, 4, 5, 4, "FF457E4DCDE9959A4B3E232526DE51B13FC020E334BC58A1C5EDE5EC4D3D42B6")]
    [InlineData(0, 8, 3, 2, "59BC942CD2F33BB97E2BAD9E0F0EAFA2D4200711391AD67F2FA2345FB15154BA")]
    [InlineData(1, 1, 17, 13, "5EEED8C81EFACA7171F90C032DB8E873F5BBDBBEBDD278CE7D2FF23B09DACBCA")]
    [InlineData(1, 2, 9, 7, "EB3B1A53CCC9C8FC03C842302C526C078815D1D5DC824888B5902FDCE7954F71")]
    [InlineData(1, 4, 5, 4, "D009201157A07B78407CB21AC125B8E425B29B9C7D28F9E4B7FD1E6B06B0F428")]
    [InlineData(1, 8, 3, 2, "3E26254112496495A9B0F9762F1BC7D36D38BBCAE5BFF70891100E788C81E68F")]
    [InlineData(2, 1, 17, 13, "C99978CB985CCBD4C192D3E2CE6E6C49674C84070DF7240F3807825CDCB715A6")]
    [InlineData(2, 2, 9, 7, "8D3CF4B09E943E5DCAA192FBE8C11A4CE2D0B6E09E5AF06740BCB38B584865A7")]
    [InlineData(2, 4, 5, 4, "B7EEF7E5CB651F832BD70AEBEE19D09CA8D7427479129C49A3C33EDD043ABE2F")]
    [InlineData(2, 8, 3, 2, "7A9D4A33DDF17D98DAF898935DC26CAD661D548AF5AE54A4E30A1CAA6B6CF0BD")]
    public void Decode_PreservesMixedFrequencySamplesAtEveryReduction(
        int fixture, int reduction, int width, int height, string expectedHash)
    {
        byte[] jpeg = Convert.FromBase64String(Fixtures[fixture]);
        var decoded = PdfJpegDecoder.DecodeImage(jpeg, 10000, reduction);

        Assert.Equal(width, decoded.Width);
        Assert.Equal(height, decoded.Height);
        Assert.Equal(expectedHash, Convert.ToHexString(SHA256.HashData(decoded.Samples)));
    }

    private static readonly string[] Fixtures =
    [
        "",
        "",
        "",
    ];
}
